var NAMES = ['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];
var PC = {C:0,'C#':1,Db:1,D:2,'D#':3,Eb:3,E:4,F:5,'F#':6,Gb:6,G:7,'G#':8,Ab:8,A:9,'A#':10,Bb:10,B:11};
var MAJOR = [0,2,4,5,7,9,11];
var MINOR = [0,2,3,5,7,8,10];
function toPC(n){ return PC[String(n).charAt(0).toUpperCase()+String(n).slice(1)]; }
function scale(root, intervals){ var r=toPC(root); return intervals.map(function(i){ return NAMES[((r+i)%12+12)%12]; }); }
function detectKey(notes){
  var pcs = notes.map(toPC).filter(function(x){return x!==undefined;});
  var major=[], minor=[];
  for(var r=0;r<12;r++){
    var mset = scale(NAMES[r], MAJOR), msetMin = scale(NAMES[r], MINOR);
    if(pcs.every(function(p){ return mset.indexOf(NAMES[p])>=0; })) major.push(NAMES[r]+' major');
    if(pcs.every(function(p){ return msetMin.indexOf(NAMES[p])>=0; })) minor.push(NAMES[r]+' minor');
  }
  return {major:major, minor:minor};
}
var EXPORTS = { NAMES:NAMES, PC:PC, MAJOR:MAJOR, MINOR:MINOR, scale:scale, detectKey:detectKey, toPC:toPC };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.KeyFinderForgePure = EXPORTS; }
